create table public.notifications (
 id uuid primary key default gen_random_uuid(), recipient_id uuid not null references auth.users(id) on delete cascade,
 category text not null check (category in ('transport','announcement')), title text not null, message text not null,
 target text not null default 'transport' check (target in ('transport','trip','assignment','announcement','fleet','schedule')),
 is_read boolean not null default false, created_at timestamptz not null default now()
);
create index notifications_recipient_time on public.notifications(recipient_id,created_at desc);
create table public.notification_event_receipts (recipient_id uuid not null references auth.users(id) on delete cascade, event_key text not null, primary key(recipient_id,event_key));
alter table public.notifications enable row level security;
alter table public.notification_event_receipts enable row level security;
revoke all on public.notifications, public.notification_event_receipts from public,anon,authenticated;
grant select,delete on public.notifications to authenticated;
grant update(is_read) on public.notifications to authenticated;
create function public.can_use_notifications() returns boolean language sql stable security definer set search_path='' as $$ select public.is_transport_admin() or exists(select 1 from public.profiles p left join public.transport_drivers d on d.id=p.driver_id where p.id=auth.uid() and (p.role='student' or (p.role='driver' and d.status<>'disabled'))) $$;
revoke all on function public.can_use_notifications() from public,anon;
grant execute on function public.can_use_notifications() to authenticated;
create policy own_inbox on public.notifications for select to authenticated using (recipient_id=(select auth.uid()) and (select public.can_use_notifications()));
create policy own_read on public.notifications for update to authenticated using (recipient_id=(select auth.uid()) and (select public.can_use_notifications())) with check (recipient_id=(select auth.uid()) and (select public.can_use_notifications()));
create policy own_delete on public.notifications for delete to authenticated using (recipient_id=(select auth.uid()) and (select public.can_use_notifications()));
create function public.emit_notice(p_user uuid,p_key text,p_category text,p_title text,p_message text,p_target text) returns void language plpgsql security definer set search_path='' as $$ begin if p_user is null then return; end if; insert into public.notification_event_receipts values(p_user,p_key) on conflict do nothing; if found then insert into public.notifications(recipient_id,category,title,message,target) values(p_user,p_category,p_title,p_message,p_target); end if; end $$;
create function public.emit_bus_notice(p_bus uuid,p_key text,p_title text,p_message text,p_target text) returns void language plpgsql security definer set search_path='' as $$ declare u uuid; begin for u in select p.id from public.profiles p join public.transport_assignments a on a.student_id=p.student_id where p.role='student' and a.bus_id=p_bus union select p.id from public.profiles p join public.transport_buses b on b.driver_id=p.driver_id join public.transport_drivers d on d.id=p.driver_id where p.role='driver' and d.status<>'disabled' and b.id=p_bus loop perform public.emit_notice(u,p_key,'transport',p_title,p_message,p_target); end loop; end $$;
create function public.emit_admin_notice(p_key text,p_title text,p_message text,p_target text) returns void language plpgsql security definer set search_path='' as $$ declare u uuid; begin for u in select user_id from public.admin_members loop perform public.emit_notice(u,p_key,'transport',p_title,p_message,p_target); end loop; end $$;
revoke all on function public.emit_notice(uuid,text,text,text,text,text),public.emit_bus_notice(uuid,text,text,text,text),public.emit_admin_notice(text,text,text,text) from public,anon,authenticated;
create function public.notify_trip_event() returns trigger language plpgsql security definer set search_path='' as $$ declare name text; begin select bus_number into name from public.transport_buses where id=new.bus_id; if tg_op='INSERT' and new.status='active' then perform public.emit_bus_notice(new.bus_id,'trip-start:'||new.id,'Journey started','Bus '||coalesce(name,'assigned')||' has started a journey.','trip'); elsif tg_op='UPDATE' and old.status='active' and new.status='completed' then perform public.emit_bus_notice(new.bus_id,'trip-end:'||new.id,'Journey completed','Bus '||coalesce(name,'assigned')||' has completed its journey.','trip'); perform public.emit_admin_notice('trip-end:'||new.id,'Journey completed','Bus '||coalesce(name,'assigned')||' has completed its journey.','trip'); end if; return new; end $$;
create trigger notification_trip after insert or update of status on public.transport_trips for each row execute function public.notify_trip_event();
create function public.notify_assignment_event() returns trigger language plpgsql security definer set search_path='' as $$ declare u uuid; sid uuid; key text:=gen_random_uuid()::text; begin if tg_op='DELETE' then sid:=old.student_id; else sid:=new.student_id; end if; if tg_op='UPDATE' and old.bus_id is not distinct from new.bus_id and old.pickup_stop_id is not distinct from new.pickup_stop_id and old.student_id is not distinct from new.student_id then return new; end if; for u in select id from public.profiles where role='student' and student_id=sid loop perform public.emit_notice(u,key,'transport','Transport assignment changed','Your bus or pickup assignment was updated. Check your portal.','assignment'); end loop; perform public.emit_admin_notice(key,'Student assignment changed','A student transport assignment was updated.','assignment'); if tg_op='DELETE' then return old; end if; return new; end $$;
create trigger notification_assignment after insert or update or delete on public.transport_assignments for each row execute function public.notify_assignment_event();
create function public.notify_bus_event() returns trigger language plpgsql security definer set search_path='' as $$ declare key text:=gen_random_uuid()::text; u uuid; begin if old.driver_id is not distinct from new.driver_id and old.route_id is not distinct from new.route_id then return new; end if; perform public.emit_bus_notice(new.id,key,'Bus or route updated','The driver or route for bus '||new.bus_number||' was updated.','assignment'); if old.driver_id is distinct from new.driver_id then for u in select id from public.profiles where role='driver' and driver_id=old.driver_id loop perform public.emit_notice(u,key,'transport','Bus assignment changed','Your previous bus assignment changed. Check your portal.','assignment'); end loop; end if; perform public.emit_admin_notice(key,'Bus assignment updated','Bus '||new.bus_number||' has an updated driver or route.','assignment'); return new; end $$;
create trigger notification_bus after update of driver_id,route_id on public.transport_buses for each row execute function public.notify_bus_event();
create function public.notify_schedule_event() returns trigger language plpgsql security definer set search_path='' as $$ declare r uuid; b uuid; key text:=gen_random_uuid()::text; begin if tg_op='DELETE' then r:=old.route_id; else r:=new.route_id; end if; for b in select id from public.transport_buses where route_id=r loop perform public.emit_bus_notice(b,key,'Schedule changed','A schedule for your assigned route was updated. Contact the transport office for details.','schedule'); end loop; if tg_op='DELETE' then return old; end if; return new; end $$;
create trigger notification_schedule after insert or update or delete on public.transport_schedules for each row execute function public.notify_schedule_event();
create function public.notify_announcement_event() returns trigger language plpgsql security definer set search_path='' as $$ declare u uuid; begin for u in select id from public.profiles union select user_id from public.admin_members loop perform public.emit_notice(u,'announcement:'||new.id,'announcement',new.title,new.message,'announcement'); end loop; return new; end $$;
create trigger notification_announcement after insert on public.transport_notices for each row execute function public.notify_announcement_event();
create function public.notify_near_stop() returns trigger language plpgsql security definer set search_path='' as $$ declare x record; metres double precision; begin if new.source<>'live' or new.trip_id is null or new.accuracy is null or new.accuracy>50 or not exists(select 1 from public.transport_trips where id=new.trip_id and status='active') then return new; end if; for x in select p.id as user_id,s.id as stop_id,s.name,s.latitude,s.longitude,'pickup' as kind from public.transport_assignments a join public.profiles p on p.student_id=a.student_id and p.role='student' join public.transport_stops s on s.id=a.pickup_stop_id where a.bus_id=new.bus_id and s.latitude is not null union all select p.id,s.id,s.name,s.latitude,s.longitude,'destination' from public.transport_assignments a join public.profiles p on p.student_id=a.student_id and p.role='student' join public.transport_trips t on t.id=new.trip_id join lateral (select stop_id from public.transport_route_stops where route_id=t.route_id order by position desc limit 1) rs on true join public.transport_stops s on s.id=rs.stop_id where a.bus_id=new.bus_id and s.latitude is not null loop metres:=6371000*acos(least(1.0,greatest(-1.0,sin(radians(new.latitude))*sin(radians(x.latitude))+cos(radians(new.latitude))*cos(radians(x.latitude))*cos(radians(new.longitude-x.longitude))))); if metres<=500 then perform public.emit_notice(x.user_id,'near:'||new.trip_id||':'||x.kind||':'||x.stop_id,'transport',case when x.kind='pickup' then 'Bus near your pickup stop' else 'Bus near route destination' end,'The latest GPS position is within approximately 500 m of '||x.name||'. This is a proximity estimate, not a confirmed arrival.','transport'); end if; end loop; return new; end $$;
create trigger notification_gps_near after insert or update on public.transport_gps for each row execute function public.notify_near_stop();
create function public.check_fleet_alerts() returns void language plpgsql security definer set search_path='' as $$ declare x record; age interval; begin if not public.is_transport_admin() then raise exception 'Not authorized' using errcode='42501'; end if; for x in select t.id,t.started_at,b.bus_number,g.recorded_at,g.source,g.trip_id from public.transport_trips t join public.transport_buses b on b.id=t.bus_id left join public.transport_gps g on g.bus_id=b.id where t.status='active' loop age:=now()-case when x.trip_id=x.id and x.source='live' then x.recorded_at else x.started_at end; if age>interval '3 minutes' then perform public.emit_admin_notice('offline:'||x.id,'Bus GPS offline','No recent valid GPS update for bus '||x.bus_number||'. Check the driver connection.','fleet'); elsif age>interval '45 seconds' then perform public.emit_admin_notice('stale:'||x.id,'Bus GPS delayed','GPS updates for bus '||x.bus_number||' are delayed.','fleet'); end if; end loop; end $$;
revoke all on function public.check_fleet_alerts() from public,anon;
grant execute on function public.check_fleet_alerts() to authenticated;
revoke all on function public.notify_trip_event(),public.notify_assignment_event(),public.notify_bus_event(),public.notify_schedule_event(),public.notify_announcement_event(),public.notify_near_stop() from public,anon,authenticated;
alter publication supabase_realtime add table public.notifications;
